import z3

n = 12
X = [[z3.Int(f'x{i}_{j}') for j in range(n)] for i in range(n)]

s = z3.Solver()

# Domain constraints
for i in range(n):
    for j in range(n):
        s.add(X[i][j] >= 0, X[i][j] < n)

# Idempotent
for i in range(n):
    s.add(X[i][i] == i)

# Latin square: rows and columns distinct
for i in range(n):
    s.add(z3.Distinct(X[i]))
    s.add(z3.Distinct([X[k][i] for k in range(n)]))

# QG3 constraints using implications
for i in range(n):
    for j in range(n):
        for k in range(n):
            for l in range(n):
                s.add(z3.Implies(z3.And(X[i][j] == k, X[j][i] == l), X[k][l] == i))

print(s.check())

